-- ============================================================
-- VRG Cerâmicas — Setup completo de pecas_estoque
-- Executa TUDO em ordem: migrações + seed de dados.
-- Execute UMA VEZ no SQL Editor do Supabase.
-- ============================================================

-- ── 1. Remover duplicatas de codigo (mantém o registro mais recente) ──────────

DELETE FROM pecas_estoque a
USING pecas_estoque b
WHERE a.ctid < b.ctid
  AND a.codigo = b.codigo;

-- ── 2. Unique em codigo apenas para peças avulsas (conjunto_id IS NULL) ───────

ALTER TABLE pecas_estoque
  DROP CONSTRAINT IF EXISTS pecas_estoque_codigo_unique;

DROP INDEX IF EXISTS pecas_estoque_codigo_avulsa_unique;

CREATE UNIQUE INDEX IF NOT EXISTS pecas_estoque_codigo_avulsa_unique
  ON pecas_estoque (codigo)
  WHERE conjunto_id IS NULL
    AND codigo IS NOT NULL
    AND btrim(codigo) <> '';

-- ── 3. Adicionar todas as colunas necessárias ─────────────────────────────────

ALTER TABLE pecas_estoque
  ADD COLUMN IF NOT EXISTS tipo_embalagem  text,
  ADD COLUMN IF NOT EXISTS tipo_argila     text,
  ADD COLUMN IF NOT EXISTS qnt_argila_kg   numeric(10, 4),
  ADD COLUMN IF NOT EXISTS esmalte_qnt_gr  numeric(10, 4),
  ADD COLUMN IF NOT EXISTS engobe_qnt_gr   numeric(10, 4),
  ADD COLUMN IF NOT EXISTS tinta_qnt_gr    numeric(10, 4),
  ADD COLUMN IF NOT EXISTS tipo_biscoito   text,
  ADD COLUMN IF NOT EXISTS tipo_queima     text,
  ADD COLUMN IF NOT EXISTS custo_extra     numeric(10, 2),
  ADD COLUMN IF NOT EXISTS preco_praticado numeric(10, 2),
  ADD COLUMN IF NOT EXISTS descricao       text,
  ADD COLUMN IF NOT EXISTS status          text NOT NULL DEFAULT 'disponivel',
  ADD COLUMN IF NOT EXISTS exibir_no_site  boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS peso            numeric(10, 3),
  ADD COLUMN IF NOT EXISTS categoria       text,
  ADD COLUMN IF NOT EXISTS fenearte        boolean NOT NULL DEFAULT false;

-- ── 4. Inserir as peças do catálogo ──────────────────────────────────────────

